const item = $input.first().json;
const payload = item.body ? item.body : item;
const rawSender = payload.from ? payload.from : (payload.sender ? payload.sender : (payload.sender_email ? payload.sender_email : "guest@enterprise.com"));
const senderMatch = String(rawSender).match(/<([^>]+)>/);
const cleanSender = senderMatch ? senderMatch[1] : String(rawSender);
const rawBody = payload.text ? payload.text : (payload.body ? payload.body : (payload.clean_body ? payload.clean_body : (payload.content ? payload.content : "")));
const cleanBody = String(rawBody).replace(/<[^>]*>?/gm, "").replace(/\r?\n|\r/g, " ").trim();
const cleanSubject = String(payload.subject ? payload.subject : "Yêu cầu hỗ trợ").replace(/\r?\n|\r/g, " ").trim();

const fullText = (cleanSubject + " " + cleanBody + " " + cleanSender).toLowerCase();
const isSpam = cleanSender.includes('spammer') || cleanSender.includes('evil.com') || fullText.includes('lua-dao') || fullText.includes('trúng thưởng') || fullText.includes('claim-now') || fullText.includes('50,000 usd') || fullText.includes('quay số');

return [{
  json: {
    ...payload,
    sender_email: cleanSender.trim(),
    sender_name: payload.sender_name || payload.name || cleanSender.split('@')[0],
    subject: cleanSubject,
    clean_body: cleanBody,
    is_spam: isSpam,
    received_at: new Date().toISOString()
  }
}];

