const emailData = $("3. Cleanse & Normalize Email").first().json;
let aiResult = {};

try {
  const rawText = $input.first().json.candidates[0].content.parts[0].text;
  aiResult = JSON.parse(rawText);
} catch (e) {
  const text = (String(emailData.subject || '') + ' ' + String(emailData.clean_body || '')).toLowerCase();

  // Kiểm tra nhu cầu mua sắm / báo giá
  const isProcurement = text.includes('báo giá') || text.includes('hợp đồng') || text.includes('bản quyền') || text.includes('mua gói') || text.includes('triển khai phần mềm') || text.includes('mua bản quyền');

  // 1. Kỹ thuật P1 (Technical P1 - Khẩn cấp: Sập server, 504 timeout, DB sập, CPU 100%)
  const isTechP1 = /(?:lỗi|mã|error)\s*(?:500|502|503|504)| (?:504|500)\s*(?:gateway|timeout|server|internal) /i.test(text)
    || text.includes('sập')
    || text.includes('database')
    || text.includes('cơ sở dữ liệu')
    || text.includes('quá tải cpu')
    || text.includes('máy chủ')
    || text.includes('không truy cập được')
    || (text.includes('khẩn cấp') && (text.includes('sự cố') || text.includes('hạ tầng') || text.includes('server')));

  // 2. Kỹ thuật P2 (Technical P2 - Nghiêm trọng: Lỗi OTP SMS, chập chờn, không gửi được, mất đồng bộ)
  const isTechP2 = text.includes('otp')
    || text.includes('sms')
    || text.includes('mã xác thực')
    || text.includes('chập chờn')
    || text.includes('không gửi được mã')
    || text.includes('không nhận được mã')
    || text.includes('đồng bộ dữ liệu')
    || (text.includes('kỹ thuật') && (text.includes('lỗi') || text.includes('sự cố') || text.includes('cổng kết nối') || text.includes('chập chờn')));

  // 3. Kỹ thuật P3 (Technical P3 - Tiêu chuẩn: Cấp lại quyền, phân quyền quản trị)
  const isTechP3 = text.includes('cấp lại quyền')
    || text.includes('cấp quyền')
    || text.includes('quyền truy cập')
    || text.includes('trang quản trị')
    || text.includes('phân quyền');

  // 4. Tài chính / Hóa đơn (Finance)
  const isFinance = text.includes('hóa đơn') || text.includes('vat') || text.includes('đối soát') || text.includes('sao kê') || text.includes('chứng từ') || emailData.filename || emailData.file_extension;

  // 5. Kinh doanh (Sales)
  const isSales = isProcurement || text.includes('bảng giá') || text.includes('chi phí') || text.includes('đặt mua') || text.includes('enterprise') || text.includes('ngân sách') || text.includes('đăng ký dùng thử');

  // 6. Hỏi đáp chung (General)
  const isGeneral = text.includes('thời gian làm việc') || text.includes('giờ làm việc') || text.includes('địa chỉ') || text.includes('chi nhánh') || text.includes('trung tâm') || text.includes('tư vấn trực tiếp') || text.includes('hỏi về') || text.includes('thắc mắc') || text.includes('quy định') || text.includes('chính sách') || text.includes('webhook');

  if (isTechP1 && !isProcurement) {
    aiResult = { category: 'Technical', priority: 'P1 - Critical', sentiment: 'Khan cap', urgency_reason: 'Sự cố hạ tầng nghiêm trọng P1' };
  } else if (isTechP2 && !isProcurement) {
    aiResult = { category: 'Technical', priority: 'P2 - High', sentiment: 'Khan cap', urgency_reason: 'Sự cố dịch vụ xác thực và giao diện P2' };
  } else if (isTechP3 && !isProcurement) {
    aiResult = { category: 'Technical', priority: 'P3 - Medium', sentiment: 'Trung tinh', urgency_reason: 'Yêu cầu quản trị phân quyền người dùng' };
  } else if (isFinance) {
    aiResult = { category: 'Finance', priority: 'P3 - Medium', sentiment: 'Trung tinh', urgency_reason: 'Yêu cầu chứng từ đối soát hóa đơn' };
  } else if (isSales) {
    aiResult = { category: 'Sales', priority: 'P2 - High', sentiment: 'Tich cuc', urgency_reason: 'Cơ hội hợp đồng kinh doanh tiềm năng' };
  } else if (isGeneral) {
    aiResult = { category: 'General', priority: 'P4 - Low', sentiment: 'Trung tinh', urgency_reason: 'Hỗ trợ thông tin chung về dịch vụ' };
  } else {
    aiResult = { category: 'General', priority: 'P4 - Low', sentiment: 'Trung tinh', urgency_reason: 'Hỗ trợ thông tin chung' };
  }
}

return [{
  json: {
    ...emailData,
    category: aiResult.category || 'General',
    priority: aiResult.priority || 'P4 - Low',
    sentiment: aiResult.sentiment || 'Trung tinh',
    urgency_reason: aiResult.urgency_reason || 'Đã phân loại tự động'
  }
}];

// Phục hồi lại dữ liệu chuẩn từ Node 8 để các node sau nhận đủ thông tin
const data = $("8. Output Schema Validator").first().json;
return [{ json: data }];

const pri = String($('14. Merge Branch Data').first().json.priority || '');
let hours = 8;
if (pri.includes('P1')) hours = 2;
else if (pri.includes('P2')) hours = 4;
else if (pri.includes('P3')) hours = 8;
else if (pri.includes('P4')) hours = 24;

const now = new Date();
now.setHours(now.getHours() + hours);
return [{ json: { target_sla: now.toISOString(), status: "SLA_ACTIVE", sla_hours: hours } }];

